// 🔴 LA ENTRADA · genérica (2026-09-12 · CC#3)
// El flujo del manual iba a buscar el manual del cliente. Éste recibe el texto
// ya escrito, así que sirve para cualquier documento — el plan de 90 días, por
// ejemplo. Todo lo de abajo (carpeta del cliente · documento · PDF · limpieza ·
// verificación · campana) es el MISMO camino que ya escribe PDFs de verdad.
/**
 * MARKDOWN → TEXTO LEGIBLE PARA EL PDF (ronda 73) · texto plano apto para pegar en un nodo Code de n8n (sin require/import/export).
 * El flujo «Texto → Drive» sube el texto como documento de Google y lo exporta a PDF; el documento NO interpreta markdown, así que el PDF salía con `#`, `**`, `---` y tablas con barras.
 * Es general (sirve a cualquier documento que llegue): no sabe de clientes ni de qué documento se trata. No toca el contenido, solo su marcado.
 */
function markdownATexto(entrada) {
  var t = String(entrada === undefined || entrada === null ? '' : entrada).split('\r\n').join('\n')
  var enCodigo = false
  var salida = []
  var lineas = t.split('\n')
  for (var i = 0; i < lineas.length; i++) {
    var l = lineas[i]
    if (/^\s*```/.test(l)) { enCodigo = !enCodigo; continue }
    if (enCodigo) { salida.push(l); continue }
    // raya horizontal (---, ***, ___): separa secciones, no es texto
    if (/^\s*([-*_])(?:\s*\1){2,}\s*$/.test(l)) { salida.push(''); continue }
    // fila de separación de tabla (|---|---|)
    if (/^\s*\|?\s*:?-{2,}:?\s*(\|\s*:?-{2,}:?\s*)*\|?\s*$/.test(l) && l.indexOf('|') >= 0) continue
    // fila de tabla → celdas separadas por « · »
    if (/^\s*\|.*\|\s*$/.test(l)) {
      l = l.trim().replace(/^\|/, '').replace(/\|$/, '').split('|').map(function (c) { return c.trim() }).filter(function (c) { return c !== '' }).join(' · ')
    }
    // título: se quitan las almohadillas (la línea queda sola, con aire)
    var h = /^\s{0,3}#{1,6}[ \t]+(.*?)\s*#*\s*$/.exec(l)
    if (h) { if (salida.length && salida[salida.length - 1] !== '') salida.push(''); l = h[1] }
    // viñetas
    l = l.replace(/^(\s*)[-*+][ \t]+/, '$1• ')
    // cita
    l = l.replace(/^\s*>[ \t]?/, '')
    salida.push(l)
  }
  var s = salida.join('\n')
  // énfasis y código en línea
  s = s.replace(/\*\*([^*\n]+?)\*\*/g, '$1').replace(/__([^_\n]+?)__/g, '$1')
  s = s.replace(/(^|[\s(«"'¿¡])\*([^*\n]+?)\*(?=[\s).,;:!?»"']|$)/g, '$1$2')
  s = s.replace(/`([^`\n]*)`/g, '$1')
  // enlaces [texto](url) → texto (url)
  s = s.replace(/\[([^\]\n]+)\]\((https?:\/\/[^)\s]+)\)/g, '$1 ($2)')
  // escapes de markdown: \# \* \_ \| \! \( \) \[ \] \- \. \\ \` \> \~
  s = s.replace(/\\([\\`*_{}\[\]()#+\-.!|>~])/g, '$1')
  // aire: no más de una línea en blanco seguida
  s = s.replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n')
  return s.replace(/^\s+/, '').replace(/\s+$/, '') + '\n'
}

const b = $input.first().json.body || $input.first().json;
// r73 · el documento de Google no interpreta markdown: se pasa a texto legible (sin # ni ** ni --- ni barras de tabla) · el texto guardado en la base no cambia
const texto = markdownATexto(String(b.texto || ''));
const faltan = [];
if (!b.client_id) faltan.push('client_id');
if (!b.client_name) faltan.push('client_name');
if (!texto.trim()) faltan.push('texto');
return [{ json: {
  hay: faltan.length === 0,
  motivo: faltan.length ? ('falta ' + faltan.join(' y ') + ' · sin eso no hay documento que escribir') : null,
  client_id: b.client_id || null,
  client_name: b.client_name || '(sin nombre)',
  nombre: b.nombre || ('Documento ' + new Date().toISOString().slice(0, 10)),
  texto: texto,
  caracteres: texto.length,
} }];

// El defecto del modulo de julio era crear SIEMPRE · su propia especificacion pedia
// "saltear si ya existe (consultar primero)" y no se construyo. Aca se consulta.
const prev = $('Seguir').first().json;
const r = $json.body || $json;
const hallada = (r.files && r.files[0]) ? r.files[0].id : null;
return [{ json: Object.assign({}, prev, { folder_id: hallada, folder_reusada: !!hallada }) }];

const prev = $('Carpeta usar o crear').first().json;
const r = $json.body || $json;
const id = prev.folder_id || r.id || null;
if (!id) { return [{ json: Object.assign({}, prev, { _parar: true, motivo: 'no se pudo obtener la carpeta del cliente' }) }]; }
return [{ json: Object.assign({}, prev, { folder_id: id }) }];

// El recibo dice lo que la RESPUESTA de Drive contesto, no lo que se pidio.
const patch = $('Nombre y carpeta del PDF').first().json;
const r = patch.body || patch;
const pdfOk = !!(r && r.id && r.name);
const prev = $('Carpeta definitiva').first().json;
// el documento temporal: Drive contesta 204 (o 200) cuando lo borra · cualquier otra cosa = NO se borro (antes se callaba)
let codigo = null, borrado = false;
try { const b = $('Borrar el documento intermedio').first().json; codigo = Number(b.statusCode); borrado = codigo === 204 || codigo === 200; } catch (e) { borrado = false; }
const ok = pdfOk && borrado;
const motivo = !pdfOk ? 'Drive no devolvio el archivo con nombre'
  : !borrado ? 'el PDF quedo en Drive pero el documento temporal NO se borro (respuesta de Drive: ' + (codigo === null || isNaN(codigo) ? 'sin codigo' : codigo) + ')'
  : null;
return [{ json: { ok, pdf_ok: pdfOk, intermedio_borrado: borrado, codigo_borrado: (codigo === null || isNaN(codigo)) ? null : codigo,
  file_id: r && r.id || null, nombre: r && r.name || null,
  url: r && r.webViewLink || null, folder_id: prev.folder_id,
  folder_reusada: !!prev.folder_reusada, client_name: prev.client_name,
  motivo } }];

// r74 · Drive tiene que devolver una CARPETA. Un archivo «Untitled» (application/octet-stream) NO es carpeta: se PARA aquí, antes de subir nada.
const prev = $('Carpeta usar o crear').first().json;
const r = $json.body || $json;
if (!r || !r.id || r.mimeType !== 'application/vnd.google-apps.folder') {
  throw new Error('DRIVE_NO_CREO_CARPETA · Drive devolvió ' + JSON.stringify(r || null).slice(0, 200) + ' (se esperaba mimeType application/vnd.google-apps.folder) · se DETIENE antes de subir nada');
}
return [{ json: Object.assign({}, prev, { folder_id: r.id, id: r.id, folder_creada: true }) }];
